// TestGenerateFrontendNav_EmitsOtel pins src/lib/otel_gen.ts as a Tier-1 file,
// which is what its banner has always claimed.
//
// It carries "Code generated by forge. DO NOT EDIT. / forge-owned:
// regenerated every run", and the banner linter's isKnownTier1 list names it
// — but for a long time nothing regenerated it. It arrived once with the
// static scaffold tree and was never written again, which made the claim
// false in BOTH directions:
//
//   - a hand-edit survived every `forge generate`, and the drift lint could
//     not flag it because no hash had ever been recorded for the path;
//   - DELETING it (the documented way to re-adopt a forge-owned file) left
//     src/app/providers.tsx importing "@/lib/otel", so `tsc --noEmit` failed
//     with TS2307 and no amount of `forge generate` brought the module back.
func TestGenerateFrontendNav_EmitsOtel(t *testing.T) {
	projectDir := t.TempDir()
	cfg := &config.ProjectConfig{
		Name: "demo",
		Frontends: []config.FrontendConfig{
			{Name: "web", Type: "nextjs"},
		},
	}
	cs := &checksums.FileChecksums{}

	if err := generateFrontendNav(cfg, nil, projectDir, nil, cs); err != nil {
		t.Fatalf("generateFrontendNav: %v", err)
	}

	rel := filepath.Join("frontends", "web", "src", "lib", "otel_gen.ts")
	body, err := os.ReadFile(filepath.Join(projectDir, rel))
	if err != nil {
		t.Fatalf("expected otel_gen.ts after generate, got: %v", err)
	}
	s := string(body)

	for _, want := range []string{
		"// Code generated by forge. DO NOT EDIT.",
		// providers.tsx imports exactly this symbol; if it moves, the
		// scaffold stops compiling.
		"export function initTelemetry(",
		// The service name is baked from the project and frontend names,
		// which is why the file has to be regenerated rather than frozen at
		// scaffold time.
		"export const SERVICE_NAME = 'demo-web';",
	} {
		if !strings.Contains(s, want) {
			t.Errorf("otel.ts missing %q; got:\n%s", want, s)
		}
	}

	// Self-certifying: the embedded forge:hash marker verifies, so hand-edits
	// trip the Tier-1 stomp guard and the stale sweep sees live codegen.
	if got := checksums.Verify(body); got != checksums.Pristine {
		t.Errorf("otel.ts Verify = %v, want Pristine (embedded forge:hash marker)", got)
	}
}

// TestGenerateFrontendNav_OtelSelfHealsAfterDeletion is the direct regression:
// deleting a forge-owned file is the documented way to re-adopt it, and the
// next generate must put it back.
func TestGenerateFrontendNav_OtelSelfHealsAfterDeletion(t *testing.T) {
	projectDir := t.TempDir()
	cfg := &config.ProjectConfig{
		Name: "demo",
		Frontends: []config.FrontendConfig{
			{Name: "web", Type: "nextjs"},
		},
	}
	cs := &checksums.FileChecksums{}

	if err := generateFrontendNav(cfg, nil, projectDir, nil, cs); err != nil {
		t.Fatalf("first generateFrontendNav: %v", err)
	}
	abs := filepath.Join(projectDir, "frontends", "web", "src", "lib", "otel_gen.ts")
	first, err := os.ReadFile(abs)
	if err != nil {
		t.Fatalf("read otel_gen.ts: %v", err)
	}
	if err := os.Remove(abs); err != nil {
		t.Fatalf("remove otel.ts: %v", err)
	}

	if err := generateFrontendNav(cfg, nil, projectDir, nil, cs); err != nil {
		t.Fatalf("second generateFrontendNav: %v", err)
	}
	second, err := os.ReadFile(abs)
	if err != nil {
		t.Fatalf("otel.ts was not restored — providers.tsx still imports it, so the scaffold no longer typechecks: %v", err)
	}
	if string(first) != string(second) {
		t.Error("otel.ts regen is not byte-identical — a no-op `forge generate` would churn the diff")
	}
}

// TestGenerateFrontendNav_OtelForNextJSAndViteNotNative: browser telemetry is
// emitted for the two web frontends, each with its own env-read spelling, and
// never for React Native. The HyperDX SDK is a browser bundle (rrweb, DOM
// instrumentation); the native scaffold installs @opentelemetry/api alone and
// has no `window` to instrument.
func TestGenerateFrontendNav_OtelForNextJSAndViteNotNative(t *testing.T) {
	projectDir := t.TempDir()
	cfg := &config.ProjectConfig{
		Name: "demo",
		Frontends: []config.FrontendConfig{
			{Name: "web", Type: "nextjs"},
			{Name: "admin", Type: "vite-spa"},
			{Name: "mobile", Type: "react-native"},
		},
	}
	cs := &checksums.FileChecksums{}

	if err := generateFrontendNav(cfg, nil, projectDir, nil, cs); err != nil {
		t.Fatalf("generateFrontendNav: %v", err)
	}

	otel := func(fe string) string {
		return filepath.Join(projectDir, "frontends", fe, "src", "lib", "otel_gen.ts")
	}
	if _, err := os.Stat(otel("mobile")); err == nil {
		t.Error("frontends/mobile received otel_gen.ts — the HyperDX browser SDK has no place in a React Native app")
	}

	for fe, want := range map[string]string{
		"web":   "process.env.NEXT_PUBLIC_OTEL_ENDPOINT",
		"admin": "import.meta.env.VITE_OTEL_ENDPOINT",
	} {
		body, err := os.ReadFile(otel(fe))
		if err != nil {
			t.Errorf("frontends/%s did not receive otel_gen.ts: %v", fe, err)
			continue
		}
		s := string(body)
		if !strings.Contains(s, want) {
			t.Errorf("frontends/%s otel_gen.ts does not read %s in project code:\n%s", fe, want, s)
		}
		if !strings.Contains(s, "export function initTelemetry(") {
			t.Errorf("frontends/%s otel_gen.ts must export initTelemetry:\n%s", fe, s)
		}
	}
	// The Vite file must not carry Next's env spelling, or vice versa: each
	// bundler inlines only its own.
	if body, err := os.ReadFile(otel("admin")); err == nil && strings.Contains(string(body), "process.env") {
		t.Errorf("vite otel_gen.ts reads process.env, which Vite does not inline:\n%s", body)
	}
}

// TestOtelServiceNameIsWhatTheObservabilityFilters is the contract between the
// two halves forge generates for a web frontend: the service.name its
// otel_gen.ts reports (SERVICE_NAME, what the browser SDK sends) and the
// service.name the generated frontend dashboard and frontend alert defaults
// filter on. They were derived separately once — "<project>-frontend" in the
// observability, while a runtime reported "<project>-<frontend>" — and every
// frontend alert matched nothing. Both now read naming.FrontendServiceName;
// this test reads the generated file, not the function, so a template that
// stops using it fails here.
func TestOtelServiceNameIsWhatTheObservabilityFilters(t *testing.T) {
	projectDir := t.TempDir()
	cfg := &config.ProjectConfig{
		Name: "demo",
		Frontends: []config.FrontendConfig{
			{Name: "web", Type: "nextjs"},
			{Name: "admin", Type: "vite-spa"},
			{Name: "mobile", Type: "react-native"},
		},
	}
	if err := generateFrontendNav(cfg, nil, projectDir, nil, &checksums.FileChecksums{}); err != nil {
		t.Fatalf("generateFrontendNav: %v", err)
	}
	serviceName := regexp.MustCompile(`(?m)^export const SERVICE_NAME = '([^']+)';$`)
	var reported []string
	for _, fe := range []string{"web", "admin"} {
		body, err := os.ReadFile(filepath.Join(projectDir, "frontends", fe, "src", "lib", "otel_gen.ts"))
		if err != nil {
			t.Fatal(err)
		}
		m := serviceName.FindStringSubmatch(string(body))
		if m == nil {
			t.Fatalf("frontends/%s otel_gen.ts declares no SERVICE_NAME:\n%s", fe, body)
		}
		if !strings.Contains(string(body), "serviceName: SERVICE_NAME,") {
			t.Errorf("frontends/%s initTelemetry does not report SERVICE_NAME:\n%s", fe, body)
		}
		reported = append(reported, m[1])
	}
	if want := []string{"demo-web", "demo-admin"}; !slices.Equal(reported, want) {
		t.Errorf("otel_gen.ts SERVICE_NAMEs = %v, want %v", reported, want)
	}

	in := obsdash.Input{Project: cfg.Name, Frontends: observedFrontends(cfg)}
	if got := obsdash.AlertInputOf(in).FrontendServices; !slices.Equal(got, reported) {
		t.Errorf("alert defaults filter on %v, the runtimes report %v", got, reported)
	}
	var frontend *obsdash.Dashboard
	for _, d := range obsdash.Build(in).Dashboards {
		if d.ID == "frontend" {
			frontend = &d
		}
	}
	if frontend == nil {
		t.Fatal("no frontend dashboard")
	}
	for _, p := range frontend.Panels {
		if p.Kind == obsdash.KindFunnel {
			continue // product events, scoped by their own steps
		}
		scoped := slices.ContainsFunc(p.Where, func(w obsdash.Predicate) bool {
			return w.Field == obsdash.FieldService && w.Op == obsdash.OpIn && slices.Equal(w.Values, reported)
		})
		if !scoped {
			t.Errorf("frontend panel %s is not scoped to service.name IN %v: %+v", p.ID, reported, p.Where)
		}
	}
}
